  found_tags = try_add_tags(found_tags, "artist:", artist);
  found_tags = try_add_tags(found_tags, "source:", url);
  found_tags = try_add_tags(found_tags, "series:", series);
  found_tags = try_add_tags(found_tags, "character:", character);
