function try_add_tags(...args: any[]) {
  let found_tags = args[0];
  let prefix = args[1];
  let tags = args[2] ?? "";
  let tags_array = tags.split(',');
  for (let tag of tags_array) {
    found_tags.push(prefix + legacyCompat.trim(tag));
  }
  return found_tags;
}
